        // x=placed+1,y=n-1-placed: x+y=n, invalid
        // Let's just do x=1, y=1 to rotate until it lands
        if(placed+1<=n-2){
            doOp(placed+1, n-placed-2);
            // elem was at n-1, in prefix (size placed+1), goes to end at position n-1. Hmm no: n-1 >= placed+1 when placed<n-2? n-1-placed>=1, placed+1<=n-2<n-1, so n-1 is NOT in prefix. n-1 is in suffix if n-1>=n-(n-placed-2)=placed+2, i.e., n-1>=placed+2, i.e., n>=placed+3, placed<=n-3. Suffix starts at placed+2. Element at n-1 is in suffix, goes to position n-1-(placed+2)= n-placed-3... that's wrong. Let me just use a different approach:
        }
        for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        while(pos!=placed){
            if(pos>0 && pos<n-1){
                doOp(pos, n-1-pos);
