                // middle is [pos..n-1-(n-1-pos))=[pos..pos], so middle has 1 elem if x+y=n-1
                // Actually x=pos, y=n-1-pos, x+y=n-1<n. Middle=[pos..pos], elem at pos goes to pos y=n-1-pos
            } else if(pos==0){
                doOp(1, max(1, n-2-placed));
            } else { // pos==n-1
                doOp(max(1,placed), 1);
            }
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if((int)ops.size()>3*n) break;
        }
        if((int)ops.size()>3*n) break;
